// Extract telemetry parameters and evaluate Time-of-Use (TOU) tariff
const item = $input.first().json.body || $input.first().json;
const powerW = Number(item.active_power_w || item.power || 0);
const voltage = Number(item.voltage_v || item.voltage || 230);
const current = Number(item.current_a || item.current || 0);
const energyKwh = Number(item.accumulated_energy_kwh || item.energy_kwh || 0);
const userEmail = item.email || "user@example.com";

const currentHour = new Date().getHours();
// Peak tariff window: 6 PM to 10 PM (18:00 - 22:00)
const isPeakHour = currentHour >= 18 && currentHour < 22;
const tariffRate = isPeakHour ? 0.35 : 0.14; // USD per kWh
const powerLimitW = isPeakHour ? 2200 : 3500; // stricter budget during peak

const hourlyCost = (powerW / 1000) * tariffRate;
const co2EmissionRate = (powerW / 1000) * 0.42; // kg CO2 per hour
const isOverloaded = powerW > powerLimitW;

return [{
  json: {
    device_id: item.device_id || "SMART-METER-01",
    timestamp: new Date().toISOString(),
    power_w: powerW,
    voltage_v: voltage,
    current_a: current,
    energy_kwh: energyKwh,
    user_email: userEmail,
    is_peak_hour: isPeakHour,
    tariff_rate: tariffRate,
    power_limit_w: powerLimitW,
    is_overloaded: isOverloaded,
    exceeded_by_w: Math.max(0, powerW - powerLimitW),
    hourly_cost_usd: Number(hourlyCost.toFixed(4)),
    co2_kg_per_hr: Number(co2EmissionRate.toFixed(4)),
    status_message: isOverloaded ? "🚨 CRITICAL: Power Exceeded Budget Limit! Load Shedding Triggered." : "✅ HEALTHY: Energy consumption within normal limits."
  }
}];
